(() => {
  const phrase = "Olá! Desejo solicitar uma proposta comercial";
  const last = $('ManyChat').first().json.body.last_input_text || "";
  const agenteRaw = $('ManyChat').first().json.body.custom_fields?.agente_pergunta || "";
  const agenteClean = agenteRaw.replace(/\{\{cuf_\d+\}\}/g, "");

  const p1 = last.includes(phrase)
    ? last.replace(phrase, "").trim().replace(/\D/g, "")
    : "";
  const p2 = agenteClean.replace(/\D/g, "");

  if (p1 && p2) {
    if (p1 === p2) return p1;
    return `protocolos divergentes: ${p1} / ${p2}`;
  }
  if (p1) return p1;
  if (p2) return p2;
  return "sem protocolo";
})()
}}

