(() => {
  const subscribed = new Date($('ManyChat').first().json.body.subscribed);
  const primeiraMensagem = new Date(
    $('ManyChat').first().json.body.custom_fields["Data e hora da primeira mensagem"]
  );
  if (
    Number.isNaN(subscribed.getTime()) ||
    Number.isNaN(primeiraMensagem.getTime())
  ) {
    return false;
  }
  const diferencaSegundos = Math.abs(
    primeiraMensagem.getTime() - subscribed.getTime()
  ) / 1000;
  return diferencaSegundos <= 15;
})()
}}

